import os, re, sys
from html.parser import HTMLParser
def fail(why):
    print('ACCEPTANCE_FAILED: ' + why, file=sys.stderr)
    sys.exit(1)
if not os.path.isfile('index.html'):
    fail('index.html is missing at the repository root')
if not os.path.isfile('README.md'):
    fail('README.md is missing')
class References(HTMLParser):
    def __init__(self):
        super().__init__()
        self.found = []
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == 'script' and a.get('src'):
            self.found.append(a['src'])
        if tag == 'link' and a.get('href') and 'stylesheet' in (a.get('rel') or '').lower():
            self.found.append(a['href'])
skip = ('.git', '.ralphex', 'node_modules')
pages = sorted(os.path.relpath(os.path.join(d, f)) for d, dirs, files in os.walk('.') if not any(p in skip for p in d.split(os.sep))
               for f in files if f.endswith('.html'))
for page in pages:
    parser = References()
    with open(page, encoding='utf-8', errors='replace') as handle:
        parser.feed(handle.read())
    for ref in parser.found:
        if re.match(r'^([a-z][a-z0-9+.-]*:)?//', ref, re.I):
            fail(page + ' loads ' + ref + ' from another site; the preview serves only files in the repository')
        path = ref.split('#')[0].split('?')[0]
        target = os.path.normpath(path.lstrip('/') if path.startswith('/') else os.path.join(os.path.dirname(page), path))
        if not os.path.isfile(target):
            fail(page + ' loads ' + ref + ', which is not a file in the repository')
        if not re.search(r'\.(m?js|css)$', target):
            fail(page + ' loads ' + ref + ', which a browser cannot run without a build step')
print('ACCEPTANCE_OK: %d page(s); index.html and README.md present; every script and stylesheet is a plain file in the repository' % len(pages))
PY
